import { CommonModule, Location } from '@angular/common';
import { Component } from '@angular/core';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { MatSelectModule } from '@angular/material/select';
import { ButtonComponent } from '../../../../../shared/components/button/button.component';
import { MatSlideToggleModule } from '@angular/material/slide-toggle';
import { ActivatedRoute, Router } from '@angular/router';
import { permissionModuleRes, permissionUpdateModuleReq } from '../../../../interfaces/permission.interface';
import { PermissionService } from '../../../../services/permission/permission.service';
import { FormsModule } from '@angular/forms';
import { UserPermissionService } from '../../../../../shared/services/user-permission/user-permission.service';
@Component({
  selector: 'app-editpermissions',
  standalone: true,
  imports: [CommonModule, IconComponent, MatSelectModule, ButtonComponent, MatSlideToggleModule, FormsModule],
  templateUrl: './editpermissions.component.html',
  styleUrl: './editpermissions.component.scss'
})
export class EditpermissionsComponent {
  nCaseid: string;
  nRoleid: string;
  cRole: string;
  nUserid: string; cFname: string; cLname: string;
  moduleList: permissionModuleRes[];
  isloading: boolean = false;
  constructor(private location: Location, private route: ActivatedRoute, private permissionS: PermissionService, private userPermissions: UserPermissionService) {
    var params = this.route.snapshot.params;
    params = JSON.parse(decodeURIComponent(params["id"]));
    this.nCaseid = params && params["id"] ? params["id"] : 0;
    this.nRoleid = params && params["role"] ? params["role"] : 0;
    this.cRole = params && params["rnm"] ? params["rnm"] : '';
    this.nUserid = params && params["user"] ? params["user"] : 0;
    this.cFname = params && params["fnm"] ? params["fnm"] : '';
    this.cLname = params && params["lnm"] ? params["lnm"] : '';

    userPermissions.userPermissionList(this.nCaseid);
  }


  async ngOnInit() {
    if (this.nRoleid) {
      this.getRoleModule();
    }
    if (this.nUserid) {
      this.getUserModule()
    }
  }

  async ResetDefaultPermission() {
    await this.permissionS.resetRoleModule(this.nCaseid, this.nRoleid, this.nUserid);
    this.ngOnInit();
  }


  async getRoleModule() {
    this.isloading = true
    this.moduleList = await this.permissionS.permissionRoleModule({ nCaseid: this.nCaseid, nRoleid: this.nRoleid });
    this.isloading = false;
  }

  async getUserModule() {
    this.isloading = true
    this.moduleList = await this.permissionS.permissionUserModule({ nCaseid: this.nCaseid, nUserid: this.nUserid });
    this.isloading = false;
  }

  back() {
    this.location.back();
  }

  updatePermission(x) {
    var mdl: permissionUpdateModuleReq = {
      nCaseid: this.nCaseid,
      nRoleid: this.nRoleid,
      nUserid: this.nUserid,
      bValue: x.bValue,
      nPMid: x.nPMid
    };
    this.permissionS.updatePermission(mdl)

  }

}
